package br.com.stockmanager.service;
import br.com.stockmanager.dto.*; import br.com.stockmanager.entity.*; import br.com.stockmanager.enums.*; import br.com.stockmanager.repository.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class StockMovementServiceTest {
 @Mock StockMovementRepository movements; @Mock ProductService products; @Mock SupplierService suppliers; @Mock UserRepository users; StockMovementService service; Product product; User user;
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new StockMovementService(movements,products,suppliers,users);product=new Product("CIM-1","Cimento",null,null,ProductUnit.SC,new BigDecimal("30"),BigDecimal.ZERO,BigDecimal.ZERO,new Category("Cimento",null));user=new User("Admin","admin@test.com","hash",UserRole.ADMIN);when(users.findByEmailIgnoreCase(user.getEmail())).thenReturn(Optional.of(user));when(movements.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void calculatesWeightedAverageCost(){product.setCurrentStock(new BigDecimal("100"));when(products.get(1L)).thenReturn(product);var item=new MovementItemRequest(1L,new BigDecimal("50"),null,new BigDecimal("36"));var result=service.create(MovementType.ENTRY,new MovementRequest("Compra",null,null,List.of(item)),user.getEmail());assertEquals(new BigDecimal("150"),product.getCurrentStock());assertEquals(new BigDecimal("32.0000"),product.getCostPrice());assertEquals(MovementType.ENTRY,result.type());}
 @Test void rejectsInsufficientExitWithoutSaving(){product.setCurrentStock(new BigDecimal("10"));when(products.get(1L)).thenReturn(product);var item=new MovementItemRequest(1L,new BigDecimal("11"),null,null);assertThrows(RuntimeException.class,()->service.create(MovementType.EXIT,new MovementRequest("Venda",ExitReason.SALE,null,List.of(item)),user.getEmail()));verify(movements,never()).save(any());assertEquals(new BigDecimal("10"),product.getCurrentStock());}
}
